type Circle = { kind: "circle"; radius: number };
type Square = { kind: "square"; side: number };
type Shape = Circle | Square;

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "square":
      return shape.side ** 2;
    default: {
      const _exhaustive: never = shape;
      return _exhaustive;
    }
  }
}

type ApiSuccess<T> = { ok: true; data: T };
type ApiFailure = { ok: false; error: string; code: number };
type ApiResult<T> = ApiSuccess<T> | ApiFailure;

function handle<T>(result: ApiResult<T>): T {
  if (!result.ok) {
    throw new Error(`[${result.code}] ${result.error}`);
  }
  return result.data; // narrowed: ok is true
}

type AddTodo = { type: "ADD_TODO"; text: string };
type ToggleTodo = { type: "TOGGLE_TODO"; id: string };
type TodoAction = AddTodo | ToggleTodo;

function reducer(state: string[], action: TodoAction): string[] {
  switch (action.type) {
    case "ADD_TODO":
      return [...state, action.text];
    case "TOGGLE_TODO":
      return state; // id available on action
    default:
      return state;
  }
}

type BadCircle = { kind: string; radius: number };
type BadSquare = { kind: string; side: number };
type BadShape = BadCircle | BadSquare;

function broken(shape: BadShape): number {
  if (shape.kind === "circle") {
    // shape is still BadCircle | BadSquare — radius not narrowed reliably
    return shape.radius; // exists on both anyway here, but pattern fails for distinct fields
  }
  return shape.side;
}
